import{_ as e,I as a,g as l,j as r}from"./chunks/framework.CjoWWfVe.js";const p=JSON.parse('{"title":"Глобальные настройки","description":"Смена языка, валюты учета и инструменты аварийного сброса данных в ОмниКрафт ЕРП.","frontmatter":{"title":"Глобальные настройки","description":"Смена языка, валюты учета и инструменты аварийного сброса данных в ОмниКрафт ЕРП.","order":16},"headers":[],"relativePath":"ru/docs/global-settings.md","filePath":"ru/docs/global-settings.md"}'),o={name:"ru/docs/global-settings.md"};function s(n,t,d,i,c,g){return a(),l("div",null,[...t[0]||(t[0]=[r('<div class="warning custom-block"><p class="custom-block-title">📌 Документация находится в разработке</p><p><strong>Уважаемые пользователи!</strong></p><p>Поскольку ОмниКрафт ЕРП сейчас находится в стадии активной бета-версии, регулярно дорабатывается и расширяется, справочные материалы также обновляются постепенно.</p><p>На данный момент воспринимайте документацию как ориентировочную — она является неполной, может временно не содержать описание некоторых функций или содержать неточности.</p></div><h1 id="⚙️-глобальные-настроики-язык-валюта-и-безопасность" tabindex="-1">⚙️ Глобальные настройки: Язык, Валюта и Безопасность <a class="header-anchor" href="#⚙️-глобальные-настроики-язык-валюта-и-безопасность" aria-label="Permalink to &quot;⚙️ Глобальные настройки: Язык, Валюта и Безопасность&quot;">​</a></h1><p>В отличие от <em>Настроек пространства</em>, которые влияют на экономику конкретного бизнеса (ставки, наценки, накладные расходы), <strong>Глобальные настройки</strong> задают фундаментальные правила работы всего приложения и вашей локальной базы данных.</p><p>Чтобы открыть их, нажмите в верхнем меню <strong>Файл ➔ Настройки программы</strong>.</p><hr><h2 id="🌍-локализация-и-валюта" tabindex="-1">🌍 Локализация и Валюта <a class="header-anchor" href="#🌍-локализация-и-валюта" aria-label="Permalink to &quot;🌍 Локализация и Валюта&quot;">​</a></h2><h3 id="_1-язык-интерфеиса" tabindex="-1">1. Язык интерфейса <a class="header-anchor" href="#_1-язык-интерфеиса" aria-label="Permalink to &quot;1. Язык интерфейса&quot;">​</a></h3><p>Программа поддерживает полную локализацию интерфейса. При самом первом запуске ОмниКрафт ЕРП автоматически сканирует язык вашей операционной системы и подстраивается под него. Вы можете в любой момент переключиться между <strong>Русским (RU)</strong> и <strong>English (EN)</strong>.</p><ul><li><strong>Как работает:</strong> Изменение языка требует полного перезапуска приложения, чтобы все системные окна, категории ДДС и справочники корректно перевелись и подгрузились из словарей.</li></ul><h3 id="_2-валюта-учета" tabindex="-1">2. Валюта учета <a class="header-anchor" href="#_2-валюта-учета" aria-label="Permalink to &quot;2. Валюта учета&quot;">​</a></h3><p>По умолчанию программа подтягивает символ национальной валюты из региональных настроек вашей ОС (например, <code>₽</code>, <code>$</code>, <code>€</code>, <code>₸</code>, <code>₺</code>). Вы можете изменить её на любую другую через удобный встроенный поиск (просто начните вводить название, например, <em>«лира»</em> или <em>«юань»</em>).</p><div class="warning custom-block"><p class="custom-block-title">Защита исторических данных</p><p>Кнопка смены валюты <strong>автоматически блокируется</strong>, как только вы начинаете вести реальный учет (создаете первую закупку, продажу или запись в ДДС). Это сделано для защиты вашей финансовой отчетности. Если бы программа позволяла на лету менять валюту с рублей на доллары, все ваши прошлые чеки, балансы и графики аналитики мгновенно превратились бы в математическую кашу. <strong>Что делать, если вы переехали в другую страну?</strong> Вам потребуется выполнить «Сброс учета» (см. ниже), чтобы начать вести книги в новой валюте с чистого листа, сохранив при этом справочники и рецепты.</p></div><hr><h2 id="☢️-опасная-зона-danger-zone" tabindex="-1">☢️ Опасная зона (Danger Zone) <a class="header-anchor" href="#☢️-опасная-зона-danger-zone" aria-label="Permalink to &quot;☢️ Опасная зона (Danger Zone)&quot;">​</a></h2><p>В нижней части окна настроек расположены инструменты для радикального вмешательства в базу данных. Эти кнопки следует использовать только осознанно.</p><h3 id="🧹-сброс-учета-очистка-истории" tabindex="-1">🧹 Сброс учета (Очистка истории) <a class="header-anchor" href="#🧹-сброс-учета-очистка-истории" aria-label="Permalink to &quot;🧹 Сброс учета (Очистка истории)&quot;">​</a></h3><p>Этот инструмент предназначен для <strong>«обнуления» операционной памяти</strong> бизнеса без потери его инфраструктуры. Он идеально подходит, если вы использовали программу в тестовом режиме, набили много черновых чеков, и теперь хотите начать вести реальные дела с чистого листа.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Что будет УДАЛЕНО (Журналы)</th><th style="text-align:left;">Что будет ОБНУЛЕНО (Остатки)</th><th style="text-align:left;">Что будет СОХРАНЕНО (Инфраструктура)</th></tr></thead><tbody><tr><td style="text-align:left;">• Вся история продаж (чеки)</td><td style="text-align:left;">• Физические остатки сырья на складе</td><td style="text-align:left;">• Всё оборудование и активы (Мастерская)</td></tr><tr><td style="text-align:left;">• Журнал складских движений</td><td style="text-align:left;">• Остатки готовой продукции (Витрина)</td><td style="text-align:left;">• Справочники сырья и ссылки на поставщиков</td></tr><tr><td style="text-align:left;">• Реестр денежных операций (ДДС)</td><td style="text-align:left;">• Сальдо кассы и история ДДС</td><td style="text-align:left;">• Все шаблоны изделий и Рецепты</td></tr><tr><td style="text-align:left;">• Очередь производства (Верстак)</td><td style="text-align:left;">• Себестоимость партий ФИФО</td><td style="text-align:left;">• Категории, упаковки, глобальные настройки</td></tr></tbody></table><p>Перед выполнением очистки программа автоматически сделает теневой бэкап базы данных. После нажатия кнопки <strong>«Очистить историю»</strong> ОмниКрафт ЕРП предложит автоматическую перезагрузку. Вы получите чистую мастерскую, готовую к инвентаризации стартовых остатков (см. <a href="./getting-started">Быстрый старт</a>).</p><h3 id="💥-полныи-сброс-factory-reset" tabindex="-1">💥 Полный сброс (Factory Reset) <a class="header-anchor" href="#💥-полныи-сброс-factory-reset" aria-label="Permalink to &quot;💥 Полный сброс (Factory Reset)&quot;">​</a></h3><p>Это кнопка «Красная таблетка». Она <strong>безвозвратно удаляет абсолютно всё</strong> из локальной базы данных SQLite.</p><ul><li>Все таблицы, справочники, рецепты, чеки, остатки, настройки и лицензионные ключи превращаются в пустоту.</li><li>При следующем запуске программа создаст базу заново, как будто вы только что скачали и установили ОмниКрафт ЕРП в самый первый раз.</li></ul><div class="danger custom-block"><p class="custom-block-title">Внимание!</p><p>Перед использованием этой функции <strong>обязательно</strong> сделайте ручной экспорт данных (<code>Файл ➔ Экспорт данных ➔ Резервная копия базы .db</code>), если есть хоть малейший шанс, что эта информация вам когда-либо понадобится. Восстановить данные после полного сброса без файла бэкапа невозможно.</p></div><hr><h2 id="🔄-автоматическая-перезагрузка" tabindex="-1">🔄 Автоматическая перезагрузка <a class="header-anchor" href="#🔄-автоматическая-перезагрузка" aria-label="Permalink to &quot;🔄 Автоматическая перезагрузка&quot;">​</a></h2><p>Любое изменение в Глобальных настройках (смена языка, валюты или сброс учета) требует пересборки конфигурации в оперативной памяти. После сохранения изменений программа предложит вам <strong>перезагрузиться сейчас</strong> или сделать это позже.</p><p>Во время перезагрузки ОмниКрафт ЕРП заботливо сохраняет геометрию вашего окна (размер и положение на экране), чтобы вы продолжили работу ровно там, где остановились.</p>',27)])])}const f=e(o,[["render",s]]);export{p as __pageData,f as default};
